#include <stdio.h>

int getResult(const int nums[], int nums_size);

int main() {
    int n;
    scanf("%d", &n);

    int nums[10];
    int nums_size = 0;

    while (n > 0) {
        nums[nums_size++] = n % 10;
        n /= 10;
    }

    int l = 0;
    int r = nums_size - 1;

    while (l < r) {
        int tmp = nums[l];
        nums[l] = nums[r];
        nums[r] = tmp;

        l++;
        r--;
    }

    printf("%d\n", getResult(nums, nums_size));

    return 0;
}

int getResult(const int nums[], int nums_size) {
    int correct = 0;

    for (int i = 0; i < nums_size; i++) {
        int fault = nums[i];
        if (fault > 4) fault--;

        for (int j = nums_size - i - 1; j > 0; j--) {
            fault *= 9;
        }

        correct += fault;
    }

    return correct;
}
